args:
{
 "$schema": "urn:agents-skills-creator:agent:v1",
 "name": "consult-advisors",
 "purpose": {
  "who": "設計で迷っている人か、その人から頼まれた AI",
  "when": "設計で迷い、複数の分野の見方を同時に聞きたいとき",
  "gets": "複数のアドバイザーの、それぞれの原典に基づく見解が、食い違いも含めて1つの答えにまとまって手元にある状態"
 },
 "role": {
  "does": [
   "相談に当たるアドバイザーを選び、同時に聞く",
   "返った見解を、一致と食い違いに分けて1つの答えにまとめる"
  ],
  "does_not": [
   {
    "what": "見解そのものを述べる（見解はアドバイザーが述べる）",
    "from": "作る人の答え"
   },
   {
    "what": "食い違う見解のどちらかを採る",
    "from": "作る人の答え"
   }
  ]
 },
 "description": "設計で迷い、複数の分野の見方を同時に聞きたいときに使う。相談に当たるアドバイザーを選んで同時に聞き、それぞれの原典に基づく見解を、一致 ・ 食い違い ・ 決めてほしいことに分けて1つの答えにまとめる。見解そのものは述べず、食い違う見解のどちらかを採らない。",
 "preconditions": [
  "相談の文がある"
 ],
 "inputs": [
  {
   "name": "相談",
   "form": "文（何を決めたいかと、対象の設計の説明）"
  }
 ],
 "outputs": [
  {
   "name": "まとめた見解",
   "form": "表（聞いたアドバイザー ・ 一致した見解 ・ 食い違い ・ 決めてほしいこと。各行に、どのアドバイザーのどの判断基準か）",
   "where": "標準出力"
  }
 ],
 "skills": [
  "ddd-advisor",
  "usecase-advisor",
  "qa-advisor",
  "ux-advisor",
  "platform-advisor",
  "meta-thinking-advisor"
 ],
 "steps": [
  {
   "id": 1,
   "kind": "call",
   "do": "相談に当たるアドバイザーに同時に聞く",
   "calls": [
    "ddd-advisor",
    "usecase-advisor",
    "qa-advisor",
    "ux-advisor",
    "platform-advisor",
    "meta-thinking-advisor"
   ],
   "choose": "相談の分野に当たるアドバイザーを、各 Skill の description で選ぶ",
   "passes": [
    "見解と根拠"
   ],
   "completion": "選んだアドバイザーのどれにも、見解と根拠か「答えなし」がある"
  },
  {
   "id": 2,
   "kind": "approve",
   "do": "一致 ・ 食い違い ・ 決めてほしいことに分けたまとめを、人が承認する",
   "completion": "作る人の承認か、直す所の一言がある"
  }
 ],
 "edge_cases": [
  {
   "id": "1a",
   "when": "アドバイザーが答えられない（分野の外 ・ 呼べない）",
   "then": "そのアドバイザーを「答えなし」と載せ、ほかのアドバイザーの答えを待つ",
   "end": "ステップ2へ進む",
   "examples": [
    "E2"
   ]
  }
 ],
 "rules": [
  {
   "rule": "両立する食い違いは並べ、両立しない食い違いは、どちらにも根拠を付けて「決めてほしいこと」へ置く",
   "why": "Agent が片方を採ると、見解を述べないという役割を外れ、作る人が根拠を見て決められない",
   "bad": "食い違う2つの見解のうち、根拠の多い方だけを答えに残す",
   "examples": [
    "E1"
   ]
  },
  {
   "rule": "まとめの各行に、どのアドバイザーのどの判断基準かを付ける",
   "why": "出どころの無い行は、どの原典に基づくのか推測なのかを作る人が見分けられない",
   "bad": "一致した見解を、アドバイザーの名前を付けずに1行にまとめる",
   "examples": [
    "E1"
   ]
  }
 ],
 "minimal_guarantees": [
  "どこで止まっても、作業フォルダのファイルは変わらない"
 ],
 "completion_criteria": [
  {
   "id": "C1",
   "criterion": "聞いたアドバイザーのどれにも、見解と根拠か「答えなし」が載っている",
   "check": "まとめの聞いたアドバイザーの行の数と、呼んだアドバイザーの数が同じ",
   "from": "目的の仮説（得るもの）から"
  },
  {
   "id": "C2",
   "criterion": "まとめの各行に、アドバイザーと判断基準の id が付いている",
   "check": "一致 ・ 食い違い ・ 決めてほしいことの各行を見る",
   "from": "目的の仮説（得るもの）から"
  }
 ],
 "examples": [
  {
   "id": "E1",
   "from": "作るときの場面",
   "covers": [
    "C1",
    "C2"
   ],
   "caller": "人が直接",
   "given": "SAS と Skill の境界をどう引くかの相談の文がある",
   "input": "SAS と Skill の境界をどう引くか、アドバイザーたちの見解をまとめて",
   "expected": "ddd-advisor ・ usecase-advisor ・ platform-advisor を聞いたと書かれ、一致した見解と食い違い（両立しないものは決めてほしいことへ）が、アドバイザーと判断基準の id 付きで並ぶ",
   "behavior": {
    "who": "設計を決める人",
    "does": "境界の引き方を複数の分野で相談する",
    "then": "分野ごとの根拠を並べて、決めることだけを選べる"
   }
  },
  {
   "id": "E2",
   "from": "作る人が挙げた別の場面",
   "covers": [
    "C1",
    "1a"
   ],
   "caller": "人が直接",
   "given": "料理の献立の相談の文がある",
   "input": "今週の献立を、アドバイザーたちに聞いて",
   "expected": "どのアドバイザーも分野の外で「答えなし」と載り、見解は無い",
   "behavior": {
    "who": "設計を決める人",
    "does": "設計でない相談をする",
    "then": "どのアドバイザーも当たらないと分かる"
   }
  }
 ]
}
